record.field:
def _normalize(plate):
    if not plate:
        return plate
    normalized = plate.strip().upper()
    normalized = ''.join(normalized.split())  # remove all spaces
    return normalized

for rec in records:
    if rec.x_plate_number:
        desired = _normalize(rec.x_plate_number)
        if rec.x_plate_number != desired:
            rec.write({'x_plate_number': desired})

current_year = datetime.datetime.now().year
min_year = 1900
max_year = current_year + 1

for rec in records:
    year_val = rec.x_car_year_of_production
    if not year_val:
        continue
    year_str = year_val.strip()
    if not year_str.isdigit() or len(year_str) != 4:
        raise UserError(f'Year must be a 4-digit year. Got {year_str}.')
    year = int(year_str)
    if year < min_year or year > max_year:
        raise UserError(
            f'Year of Production must be between {min_year} and {max_year}. Got {year}.'
        )
    # Normalize stored value (trim whitespace)
    if year_val != year_str:
        rec.write({'x_car_year_of_production': year_str})
